function ResultDetails({row, runId, plugin}: {row: MatrixRow; runId: string; plugin: string}) {
  const [detailLimit,setDetailLimit]=useState(30);
  const [result,setResult]=useState<unknown>(null);
  const [error,setError]=useState('');
  const [loading,setLoading]=useState(false);
  useEffect(()=>{
    let active=true;
    setResult(null); setError('');
    if (!runId || row.attempt===null || row.stale || row.status==='invalid') { setLoading(false); return; }
    setLoading(true);
    void readLegacy('ui.test_tool.result.get',{plugin,config_id:row.id,run_id:runId,attempt:row.attempt})
      .then(value=>{if(active)setResult(value);})
      .catch(reason=>{if(active)setError(reason instanceof Error?reason.message:String(reason));})
      .finally(()=>{if(active)setLoading(false);});
    return ()=>{active=false;};
  },[plugin,runId,row.id,row.attempt,row.stale,row.status]);
  const response=object(result), value=object(response.value);
  const evidence=Array.isArray(response.evidence)?response.evidence:[];
  const measurements=Array.isArray(value.results)?value.results:[];
  return <>
    {row.validation.length>0 && <div className="detail-warning"><strong><LocalizedLabel text={"配置校验问题"}/></strong>{row.validation.map((v,i)=><div key={i}>{v}</div>)}</div>}
    {loading && <div className="detail-help"><LocalizedLabel text={"正在读取结果…"}/></div>}
    {error && <div className="detail-warning"><LocalizedLabel text={"结果读取失败："}/>{error}</div>}
    {response.available===false && <div className="detail-help">{response.error ? `结果不可用：${string(response.error)}` : localizeLabel("该项暂无结果证据。")}</div>}
    {response.available===true && <div className="result-details"><small>判定 {measurements.length} 项 · 证据 {evidence.length} 项</small>{Math.max(measurements.length,evidence.length)>detailLimit&&<button className="button secondary" onClick={()=>setDetailLimit(value=>value+100)}>显示更多明细</button>}
      {object(value.identity).identity_source==='simulation' && <div className="detail-warning"><LocalizedLabel text={"模拟结果，不代表实物验证。"}/></div>}
      {measurements.length>0 && <><h4><LocalizedLabel text={"判定明细"}/></h4>{measurements.slice(0,detailLimit).map((entry,i)=>{const m=object(entry);const measured=typeof m.measured==='number'||typeof m.measured==='string'?String(m.measured):'—';return <div className="result-rule" key={i}><span>{string(m.id,`规则 ${i+1}`)}</span><strong>{string(m.verdict,'—')}</strong><small>{measured}{typeof m.unit==='string'?` ${m.unit}`:''}</small></div>})}</>}
      {evidence.length>0 && <><h4><LocalizedLabel text={"证据文件"}/></h4>{evidence.slice(0,detailLimit).map((entry,i)=>{const e=object(entry);return <div className="result-evidence" key={i}><span>{string(e.label,'文件')}</span><small>{e.available===true?localizeLabel("可用"):localizeLabel("不可用")}</small></div>})}</>}
    </div>}
  </>;
}

